import re, zlib
def score(program):
    h = lambda s: zlib.crc32(s.encode()) / 4294967296
    toks = set(re.findall(r"\w+", program)) or {"x"}
    acc = 0.0
    for salt in "abc":
        best = min(toks, key=lambda t: h(salt + t))
        acc += h(best + salt)
    return acc / 3

